      for (let i = r.int(1, big ? 4 : 3); i > 0; i--) parts.push(ex(d - 1));
      return op + "(" + parts.join(",") + ")";
    };
    if (big) {
      // a long top-level list of medium formulas, about 20 000 characters
      const parts = [];
      let len = 0;
      while (len < 19000) { const e = ex(5); parts.push(e); len += e.length + 1; }
      return [r.pick(["&", "|"]) + "(" + parts.join(",") + ")"];
    }
    return [ex(r.int(0, 4))];
  }

