function evaluateFormula(formula: string): boolean {
  let s = formula;
  while (s.length > 1) {
    s = s.replace(/[!&|]\(([tf,]*)\)/g, (_, inner: string) => {
      const op = _[0], vals = inner.split(",");
      if (op === "!") return vals[0] === "t" ? "f" : "t";
      if (op === "&") return vals.every(v => v === "t") ? "t" : "f";
      return vals.some(v => v === "t") ? "t" : "f";
    });
  }
  return s === "t";
}

