class Solution:
    def evaluateFormula(self, formula: str) -> bool:
        import re
        pat = re.compile(r"([!&|])\(([tf,]*)\)")

        def reduce(m):
            op, vals = m.group(1), m.group(2).split(",")
            if op == "!":
                return "f" if vals[0] == "t" else "t"
            if op == "&":
                return "t" if all(v == "t" for v in vals) else "f"
            return "t" if any(v == "t" for v in vals) else "f"

        s = formula
        while len(s) > 1:
            s = pat.sub(reduce, s)
        return s == "t"

