function evaluateFormula(formula: string): boolean {
  const st: string[] = [];
  for (const ch of formula) {
    if (ch === ",") continue;
    if (ch !== ")") { st.push(ch); continue; }
    let seenT = false, seenF = false;
    while (st[st.length - 1] !== "(") {
      if (st.pop() === "t") seenT = true; else seenF = true;
    }
    st.pop(); // the "("
    const op = st.pop();
    const val = op === "!" ? seenF : op === "&" ? !seenF : seenT;
    st.push(val ? "t" : "f");
  }
  return st[0] === "t";
}

