        st = []
        for ch in formula:
            if ch == ",":
                continue
            if ch != ")":
                st.append(ch)
                continue
            seen = set()
            while st[-1] != "(":
                seen.add(st.pop())
            st.pop()  # the "("
            op = st.pop()
            if op == "!":
                val = "f" in seen
            elif op == "&":
                val = "f" not in seen
            else:
                val = "t" in seen
            st.append("t" if val else "f")
        return st[0] == "t"

