function evaluateFormula(formula: string): boolean {
  let i = 0;
  const parse = (): boolean => {
    const ch = formula[i++];
    if (ch === "t") return true;
    if (ch === "f") return false;
    i++; // skip "("
    const parts: boolean[] = [parse()];
    while (formula[i] === ",") { i++; parts.push(parse()); }
    i++; // skip ")"
    if (ch === "!") return !parts[0];
    if (ch === "&") return parts.every(Boolean);
    return parts.some(Boolean);
  };
  return parse();
}

